import time
def t(f):
    try: r = f(); print(repr(r))
    except Exception as e: print(type(e).__name__, e)
S = time.struct_time
t(lambda: S((2024,1,2,3,4,5,0,2,0)))
t(lambda: S((2024,1,2,3,4,5,0,2,0,"CET")))
t(lambda: S((2024,1,2,3,4,5,0,2,0,"CET",3600)))
t(lambda: S((2024,1,2,3,4,5,0,2,0,"CET",3600,1)))
t(lambda: S((2024,1,2)))
t(lambda: S())
t(lambda: S(5))
t(lambda: S([1,2,3,4,5,6,7,8,9]))
t(lambda: S((1,2,3,4,5,6,7,8,9), {"tm_zone":"X"}))
t(lambda: S((1,2,3,4,5,6,7,8,9), 3))
t(lambda: S((1,2,3,4,5,6,7,8,9), None))
t(lambda: S(sequence=(1,2,3,4,5,6,7,8,9)))
t(lambda: S((1,2,3,4,5,6,7,8,9), {}, 3))
x = S((2024,1,2,3,4,5,0,2,0,"CET",3600))
print(x.tm_zone, x.tm_gmtoff, len(x), x[0], x[-1], x[2:4], tuple(x), x == (2024,1,2,3,4,5,0,2,0))
y = S((2024,1,2,3,4,5,0,2,0))
print(y.tm_zone, y.tm_gmtoff, y.tm_year, y.tm_isdst)
print(time.asctime(y))
print(time.strftime("%Y-%m-%d %H:%M:%S %a %b %j", y))
t(lambda: time.mktime(S((2024,1,2,3,4,5,0,2,-1))) > 0)
t(lambda: time.mktime(S((2024,1,2,3,4,5,0,2,0))) > 0)
t(lambda: time.mktime((2024,1,2,3,4,5,0,2,0)) > 0)
t(lambda: S((2024,1,2,3,4,5,0,2,0)) == S((2024,1,2,3,4,5,0,2,0)))
t(lambda: x.__reduce__())
t(lambda: S.n_fields)
t(lambda: S.n_sequence_fields)
t(lambda: S.__name__)
t(lambda: S.__module__)
t(lambda: S((0,1,1,0,0,0,0,1,0)).tm_year)
t(lambda: S((2024,1,2,3,4,5,0,2,0,5)))
t(lambda: time.asctime(S((2024,1,2,3,4,5,0,2,0))))
t(lambda: time.asctime((2024,1,2,3,4,5,0,2,0)))
